  SEARCH_TERMS: 'SEARCH_TERMS', POLICY: 'POLICY', LEARNING_LIMITED: 'LEARNING',
};
const PRIORITY_ORDER = { P1: 0, P2: 1, P3: 2 };

// BigQuery nodes run with "Always Output Data", so an empty result is one empty item.
const rows = (items) => items.map((i) => i.json).filter((j) => j && Object.keys(j).length > 0);

// Alert-ID custom field text -> Set of alert keys.
const parseKeys = (text) => new Set(String(text || '').split(/[\s,;]+/).map((s) => s.trim()).filter(Boolean));

// Open tasks of the Asana project (paginated HTTP output) -> [{gid, name, url, keys:Set, priority}]
function openTasks(items, alertFieldGid, priorityFieldGid) {
  return unwrap(items, 'data').map((t) => {
    const cf = (gid) => (t.custom_fields || []).find((c) => c.gid === gid);
    const alert = cf(alertFieldGid);
    const prio = priorityFieldGid ? cf(priorityFieldGid) : null;
    return {
      gid: t.gid,
      name: t.name,
      url: t.permalink_url,
      keys: parseKeys(alert && (alert.text_value ?? alert.display_value)),
      priority: prio ? ((prio.enum_value && prio.enum_value.name) || prio.display_value || '') : '',
    };
  });
}

// A finding turned into a task without AI (fallback, or update of an already-open task).
function taskFromFinding(f, source) {
  return {
    alert_keys: [f.alert_key],
    title: f.title.slice(0, 120),
    country: f.country,
    platform: f.platform,
    type: RULE_TYPE[f.rule] || 'PERFORMANCE',
    priority: f.severity,
    diagnosis: f.summary_line,
    action_steps: f.suggested_steps || [],
    expected_impact: '',
    expected_impact_eur: 0,
    campaign_id: f.campaign_id || '',
    source,
    findings: [f],
  };
}

// ---- wf6_compose.js ----
// Claude commentary (or a fallback note) + KPI table -> Asana project status update.
const cfg = $('Config').first().json;
const b = $('Build Weekly').first().json;
const res = $input.first().json || {};
const ai = res.stop_reason && res.stop_reason !== 'refusal'
  ? (res.content || []).filter((c) => c.type === 'text').map((c) => c.text).join('').trim()
  : '';

const line = (r) => `• ${r.krajina} ${r.platforma}: náklady ${eur(r.naklady_7d)}, ROAS ${fmt(r.roas_7d)} (min. týždeň ${fmt(r.roas_minuly_tyzden)}, cieľ ${fmt(r.ciel_roas)}), MTD ${eur(r.mtd_naklady)}${r.projekcia_vs_rozpocet === null ? '' : ` / projekcia ${pct(r.projekcia_vs_rozpocet)} vs. rozpočet`}`;
const text = [
  ai || '(AI komentár nie je k dispozícii, nižšie sú iba čísla.)',
  '',
  `SPOLU 7 dní: náklady ${eur(b.totals.cost)}, obrat ${eur(b.totals.value)}, ROAS ${fmt(safeDiv(b.totals.value, b.totals.cost))}. Otvorené úlohy agenta: ${b.open_count}.`,
  '',
  'KRAJINY',
  ...b.table.map(line),
  '',
  '🤖 Vygenerované PPC agentom (n8n).',
].join('\n');

return [{
  json: {
    status_body: {
      data: {
        parent: cfg.asana.project_gid,
        status_type: b.status_type,
        title: `Týždenný stav PPC – týždeň do ${cfg.yesterday}`,
        text,
      },
    },
    email_subject: `Balabim PPC – týždenný stav do ${cfg.yesterday}`,
    email_text: text,
  },
}];
